userRatings.sort((a, b) => {
    const dateA = new Date(a.inserted_at || 0);
    const dateB = new Date(b.inserted_at || 0);
    return dateB - dateA; // новые сначала
});

const allGames = collections[/* GamesLinkedUserRatings */ 'c49d05f7-bb03-4fbe-8983-da5e6cd10403'].data;

return userRatings.map(r => {
    const game = allGames.find(g => g.id === r.game_id);
    if (!game) return null;
    return {
        ...game,
        userRating: r.ratingvalue
    };
}).filter(Boolean).slice(0, 5); // Берем только первые 5 элементов

