const raw = variables['0eddc282-29f1-49b1-b087-0747cb7aa99e'];

const dna = raw?.stats || raw?.[0]?.stats || {};

const bias = Number(dna?.taste ?? 0);
const volatility = Number(dna?.emotions ?? 0);
const deep = Number(dna?.depth ?? 0);

// защита от NaN
const safeBias = isNaN(bias) ? 0 : bias;
const safeVolatility = isNaN(volatility) ? 0 : volatility;
const safeDeep = isNaN(deep) ? 0 : deep;

// --- 1. TASTE
let tasteLabel = '';
let tasteDesc = '';
let tasteLabelEng = '';
let tasteDescEng = '';

let tasteScore = Math.max(0, Math.min(100, 50 + safeBias * 50));

if (safeBias < -0.7) {
  tasteLabel = 'Строгий';
  tasteDesc = 'Оценки ниже среднего уровня';

  tasteLabelEng = 'Strict';
  tasteDescEng = 'Rates lower than the average player';
} else if (safeBias < -0.2) {
  tasteLabel = 'Сдержанный';
  tasteDesc = 'Оценки немного строже большинства';

  tasteLabelEng = 'Reserved';
  tasteDescEng = 'Rates slightly stricter than average';
} else if (safeBias <= 0.2) {
  tasteLabel = 'Как у большинства';
  tasteDesc = 'Оценки соответствуют общему мнению';

  tasteLabelEng = 'Mainstream';
  tasteDescEng = 'Ratings align with the general consensus';
} else if (safeBias <= 0.7) {
  tasteLabel = 'Независимый';
  tasteDesc = 'Оценки часто отличаются от большинства';

  tasteLabelEng = 'Independent';
  tasteDescEng = 'Often differs from the majority';
} else {
  tasteLabel = 'Открывает шедевры';
  tasteDesc = 'Находит ценность вне общего мнения';

  tasteLabelEng = 'Hidden Gem Finder';
  tasteDescEng = 'Finds value beyond common opinion';
}

// --- 2. EMOTIONS
let emoLabel = '';
let emoDesc = '';
let emoLabelEng = '';
let emoDescEng = '';

let emoScore = Math.max(0, Math.min(100, (safeVolatility / 3) * 100));

if (safeVolatility < 1.3) {
  emoLabel = 'Хладнокровный';
  emoDesc = 'Стабильные и предсказуемые оценки';

  emoLabelEng = 'Calm';
  emoDescEng = 'Stable and consistent ratings';
} else if (safeVolatility < 2) {
  emoLabel = 'Сбалансированный';
  emoDesc = 'Эмоции умеренно влияют на оценки';

  emoLabelEng = 'Balanced';
  emoDescEng = 'Emotions moderately influence ratings';
} else if (safeVolatility < 2.8) {
  emoLabel = 'Эмоциональный';
  emoDesc = 'Сильная зависимость от впечатления';

  emoLabelEng = 'Emotional';
  emoDescEng = 'Strong influence of impressions on ratings';
} else {
  emoLabel = 'Радикальный';
  emoDesc = 'Крайние оценки без середины';

  emoLabelEng = 'Extreme';
  emoDescEng = 'Tends toward extreme ratings';
}

// --- 3. DEPTH
let depthLabel = '';
let depthDesc = '';
let depthLabelEng = '';
let depthDescEng = '';

let depthScore = Math.max(0, Math.min(100, (safeDeep / 30) * 100));

if (safeDeep < 5) {
  depthLabel = 'Поверхностный';
  depthDesc = 'Минимальный анализ при оценке';

  depthLabelEng = 'Surface-level';
  depthDescEng = 'Minimal analysis when rating';
} else if (safeDeep < 15) {
  depthLabel = 'Вовлечённый';
  depthDesc = 'Базовое понимание игр';

  depthLabelEng = 'Engaged';
  depthDescEng = 'Basic understanding of games';
} else if (safeDeep < 30) {
  depthLabel = 'Продвинутый';
  depthDesc = 'Хорошее понимание механик';

  depthLabelEng = 'Advanced';
  depthDescEng = 'Strong understanding of game mechanics';
} else {
  depthLabel = 'Аналитик';
  depthDesc = 'Глубокий анализ игр';

  depthLabelEng = 'Analyst';
  depthDescEng = 'Deep analysis of games';
}

// --- OUTPUT
return {
  taste: {
    title: 'Вкус против системы',
    title_eng: 'Taste vs System',
    label: tasteLabel,
    label_eng: tasteLabelEng,
    description: tasteDesc,
    description_eng: tasteDescEng,
    value: tasteScore
  },
  emotions: {
    title: 'Эмоциональный размах',
    title_eng: 'Emotional Range',
    label: emoLabel,
    label_eng: emoLabelEng,
    description: emoDesc,
    description_eng: emoDescEng,
    value: emoScore
  },
  depth: {
    title: 'Глубина анализа',
    title_eng: 'Depth of Analysis',
    label: depthLabel,
    label_eng: depthLabelEng,
    description: depthDesc,
    description_eng: depthDescEng,
    value: depthScore
  }
};

