const dateStr = context.component?.variables?.[/* Date and Time picker - value */ '74608515-53ca-491f-aadf-daac1ac90b56-value'];

if (!dateStr?.trim()) {
    // Если поле пустое, берем из context.item.data?.['value']
    return context.item.data?.['value'] || '';
}

const date = new Date(dateStr);
if (isNaN(date.getTime())) {
    // Если дата невалидная, тоже берем из context.item.data
    return context.item.data?.['value'] || '';
}

const day = date.getDate();
const monthNames = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
const month = monthNames[date.getMonth()];
const year = date.getFullYear();

return `${day} ${month} ${year}`;

