// Get form values
  const formData = variables['change_password_form-form'];
  const currentPassword = formData?.fields?.currentPassword?.value;
  const newPassword = formData?.fields?.newPassword?.value;
  const confirmPassword = formData?.fields?.confirmPassword?.value;

  // Reset messages
  context.component.variables['errorMessage'] = '';
  context.component.variables['successMessage'] = '';

  // Validate passwords
  if (!currentPassword || !newPassword || !confirmPassword) {
    context.component.variables['errorMessage'] = 'All fields are required';
    return;
  }

  if (newPassword !== confirmPassword) {
    context.component.variables['errorMessage'] = 'New passwords do not match';
    return;
  }

  if (newPassword.length < 8) {
    context.component.variables['errorMessage'] = 'Password must be at least 8 characters';
    return;
  }

  // Set loading state
  context.component.variables['isLoading'] = true;

  // Simulate API call with timeout
  setTimeout(async () => {
    try {
      // Show success message
      context.component.variables['successMessage'] = 'Password changed successfully';
      context.component.variables['isLoading'] = false;

      // Reset form after 2 seconds and close popup
      setTimeout(async () => {
        await utilsFunctions.closePopup(context);
      }, 2000);
    } catch (error) {
      context.component.variables['errorMessage'] = 'An error occurred. Please try again.';
      context.component.variables['isLoading'] = false;
    }
  }, 1500);

