  // Validate input
  if (!context.parameters['newValue']) {
    context.component.variables['errorMessage'] = 'This field cannot be empty';
    return;
  }

  // Set loading state
  context.component.variables['isLoading'] = true;
  context.component.variables['errorMessage'] = '';

  // Validate email format if field is email
  if (field === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(context.parameters['newValue'])) {
    context.component.variables['errorMessage'] = 'Please enter a valid email address';
    context.component.variables['isLoading'] = false;
    return;
  }

  // Validate username length if field is username
  if (field === 'username' && context.parameters['newValue'].length < 3) {
    context.component.variables['errorMessage'] = 'Username must be at least 3 characters';
    context.component.variables['isLoading'] = false;
    return;
  }

  // Validate avatar URL if field is avatar
  if (field === 'avatar' && !context.parameters['newValue'].startsWith('http')) {
    context.component.variables['errorMessage'] = 'Please enter a valid image URL';
    context.component.variables['isLoading'] = false;
    return;
  }

  // Simulate API call with timeout
  setTimeout(async () => {
    try {
      // Update the user data
      const currentUser = variables['fd8b3a6a-6246-4c95-8798-93cde82e7ef6'] || {};
      const updatedUser = { ...currentUser };
      updatedUser[field] = context.parameters['newValue'];

      // Update the global variable
      variables['fd8b3a6a-6246-4c95-8798-93cde82e7ef6'] = updatedUser;

      // Close the popup
      await utilsFunctions.closePopup(context);
    } catch (error) {
      context.component.variables['errorMessage'] = 'An error occurred. Please try again.';
      context.component.variables['isLoading'] = false;
    }
  }, 1000);
